message.content:
{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR_FAILURE",
      "definition": "A subsequent agent action attempts to resolve a failure or missing prerequisite identified during an earlier execution step.",
      "source_description": "An earlier observed execution failure, such as a required command or dependency being unavailable.",
      "target_description": "A subsequent agent action intended to resolve that failure by establishing the missing prerequisite."
    },
    {
      "name": "ESTABLISHED_PREREQUISITE_ENABLES_ACTION",
      "definition": "A previously completed setup or prerequisite result is relied upon to make a subsequent execution action possible.",
      "source_description": "A confirmed result of a prior setup or installation action that provides a required capability or environment.",
      "target_description": "A later execution action that depends on the established prerequisite being available."
    },
    {
      "name": "VERIFIES_REPORTED_ARTIFACT",
      "definition": "A separate check performed to determine whether an artifact claimed to have been produced by an earlier execution result actually exists and contains valid content.",
      "source_description": "An earlier execution result reporting successful creation or saving of an output artifact.",
      "target_description": "An independent verification action that inspects the existence and content of the reported artifact."
    },
    {
      "name": "USES_DIAGNOSTIC_OBSERVATION_TO_SELECT_ACTION",
      "definition": "An environmental or diagnostic observation is used to determine the appropriate subsequent command or action.",
      "source_description": "A diagnostic observation about the execution environment or system state.",
      "target_description": "A subsequently selected action chosen based on that diagnostic observation."
    },
    {
      "name": "DECLARES_COMPLETION_BASED_ON_VERIFIED_RESULTS",
      "definition": "A final completion decision is made and grounded in previously verified successful execution results and validated artifacts.",
      "source_description": "A set of previously verified successful results and validated output artifacts.",
      "target_description": "A subsequent agent declaration that the task is complete and ready for grading."
    }
  ]
}

